WITH filtered AS (SELECT *, CONCAT_WS(',', device, browser) AS device_browser_key, DATE_TRUNC('month', started_at) AS started_at_period, COALESCE(browser, 'NONE') AS resolved_browser FROM sessions WHERE started_at >= TO_TIMESTAMP('2023-12-07 02:00:00') AND country IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(started_at_period) OVER (PARTITION BY customer_id ORDER BY started_at_period, id) IS NULL OR started_at_period > LAG(started_at_period) OVER (PARTITION BY customer_id ORDER BY started_at_period, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM filtered), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY customer_id ORDER BY started_at_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT device, ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN browser = 'Edge' THEN 1 END), 0), 2) AS session_start_flag_per_edge, MAX(session_no) AS max_session_no FROM islands GROUP BY device ORDER BY device NULLS FIRST
